/** Disposable P47-5A browser feasibility: NOT Practice Desk's authoring UI.
 * Exact vendor versions are isolated to artifacts generated by the source probe.
 */
import {chromium,firefox,webkit} from "playwright-core";
import {spawnSync} from "node:child_process";
import {resolve,join} from "node:path";
import {pathToFileURL} from "node:url";
import {stat} from "node:fs/promises";
const kind=process.argv[2]??"chromium";
if(!["chromium","firefox","webkit"].includes(kind))throw Error("Unknown browser "+kind);
const fixture=resolve("artifacts/p47-5a/vendor-fixture.html");
await stat(fixture);
const config={headless:true};
if(kind==="chromium"){
 const candidate=["google-chrome","google-chrome-stable","chromium","chromium-browser"].find(command=>
  spawnSync(command,["--version"],{encoding:"utf8"}).status===0);
 if(!candidate)throw Error("Chrome binary missing");
 config.executablePath=spawnSync("which",[candidate],{encoding:"utf8"}).stdout.trim();
 config.args=["--no-sandbox","--disable-dev-shm-usage","--disable-background-networking"];
}
const browser=await ({chromium,firefox,webkit})[kind].launch(config);
const errors=[],external=[];
try{
 const context=await browser.newContext({viewport:{width:390,height:844},reducedMotion:"reduce"});
 const page=await context.newPage();
 page.setDefaultTimeout(12000);
 page.on("pageerror",e=>errors.push(String(e)));
 page.on("request",r=>{if(/^https?:/i.test(r.url()))external.push(r.url());});
 await page.goto(pathToFileURL(fixture).href,{waitUntil:"load"});
 if(await page.locator(".katex-mathml").count()!==1)throw Error("KaTeX rendered HTML+MathML absent");
 for(let iteration=0;iteration<2;iteration++){
  await page.locator("#launch").click();
  await page.locator("wg-content").waitFor({state:"visible"});
  if(await page.locator("wg-content").count()!==1)throw Error("Duplicate Wordgard editor");
  if(!await page.evaluate(()=>window.p47Editor?.connected))throw Error("Wordgard did not connect");
  const initial=await page.locator("wg-content").innerText();
  if(!initial.includes("Start text"))throw Error("Wordgard did not parse its initial document");
  if(await page.locator("wg-content table").count()!==1)throw Error("Table extension did not parse table");
  await page.locator("wg-content").click();
  await page.keyboard.insertText("typed");
  const changed=await page.locator("wg-content").innerText();
  if(!changed.includes("typed"))throw Error("IME-like text input not handled");
  await page.keyboard.press("Control+z");
  await page.locator("#close").click();
  if(await page.locator("wg-content").count()!==0)throw Error("Editor not removed");
  if(await page.evaluate(()=>document.activeElement?.id)!=="launch")
    throw Error("Focus did not return after editor close");
  if(await page.evaluate(()=>window.p47Editor?.connected))
    throw Error("Wordgard connected state survived removal");
 }
 await page.setViewportSize({width:195,height:844});
 if(await page.locator(".katex-mathml").count()!==1)throw Error("MathML lost at narrow width");
 if(errors.length||external.length)throw Error("Browser errors or network:"+JSON.stringify({errors,external}));
 console.log("P47-5A VENDOR PROBE PASS "+kind+": file:// Wordgard table/type/undo/teardown/reopen and KaTeX MathML, no network");
 await context.close();
}finally{await browser.close();}
